Firebase.appCheck.installAppCheckProviderFactory(
 //YourCustomAppCheckProviderFactory(),
 DebugAppCheckProviderFactory.getInstance()
)

class YourCustomAppCheckToken(
 private val token: String,
 private val expiration: Long,
) : AppCheckToken() {
 override fun getToken(): String = token
 override fun getExpireTimeMillis(): Long = expiration
}

class YourCustomAppCheckProvider(firebaseApp: FirebaseApp) : AppCheckProvider {
 override fun getToken(): Task<AppCheckToken> {
 // Logic to exchange proof of authenticity for an App Check token and
 // expiration time.
 // ...

 // Refresh the token early to handle clock skew.
 val expMillis = expirationFromServer * 1000L - 60000L

 // Create AppCheckToken object.
 val appCheckToken: AppCheckToken = YourCustomAppCheckToken(tokenFromServer, expMillis)
 return Tasks.forResult(appCheckToken)
 }
}


class YourCustomAppCheckProviderFactory : AppCheckProviderFactory {
 override fun create(firebaseApp: FirebaseApp): AppCheckProvider {
 // Create and return an AppCheckProvider object.
 return YourCustomAppCheckProvider(firebaseApp)
 }
}"},{"role":"assistant","content":[{"type":"text","text":"Now let me check the Android configuration files to understand the App Check setup:"}],"tool_calls":[{"id":"toolu_bdrk_01VLGVZ2GWB83aibkpnjEgB3","type":"function","function":{"name":"read_file","arguments":"{"target_file": "android/app/build.gradle"}"}},{"id":"toolu_bdrk_01EATSvXQre8BNzrMQcuXz6c","type":"function","function":{"name":"list_dir","arguments":"{"target_directory": "android/app/src/main"}"}}]},{"role":"tool","name":"read_file","tool_call_id":"toolu_bdrk_01VLGVZ2GWB83aibkpnjEgB3","content":"plugins {
