import 'package:firebase_auth/firebase_auth.dart' hide EmailAuthProvider;
import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import 'package:provider/provider.dart';

import 'Eventos_Page.dart';
import 'InicioSesion.dart';

import 'app_state.dart';
import 'auth_gate.dart';

import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_app_check/firebase_app_check.dart';
import 'firebase_options.dart';
import 'package:firebase_analytics/firebase_analytics.dart';
import 'package:firebase_ui_auth/firebase_ui_auth.dart';
import 'package:firebase_ui_oauth_google/firebase_ui_oauth_google.dart';
import 'package:google_fonts/google_fonts.dart';

AndroidProvider _getAndroidProvider() {
 if (kDebugMode) {
 return AndroidProvider.debug;
 } else {
 // For release builds, use SafetyNet for APK distribution
 // SafetyNet works for both sideloaded APKs and Play Store apps
 return AndroidProvider.safetyNet;
 }
}

Future<void> main() async {
 WidgetsFlutterBinding.ensureInitialized();

 await Firebase.initializeApp(
 options: DefaultFirebaseOptions.currentPlatform,
 );

 // Configure App Check based on build mode and distribution
 await FirebaseAppCheck.instance.activate(
 androidProvider: _getAndroidProvider(),
 );

 FirebaseAnalytics analytics = FirebaseAnalytics.instance;

 FirebaseUIAuth.configureProviders([
 EmailAuthProvider(),
 GoogleProvider(
 clientId:
 '650790578068-cv2q1uh5dqghs0a7o00cvq1qgrnr3m9k.apps.googleusercontent.com'),
 ]);

 runApp(ChangeNotifierProvider(
 create: (context) => ApplicationState(),
 builder: ((context, child) => MyApp()),
 ));
}

Future<void> initializeDefault() async {
 FirebaseApp app = await Firebase.initializeApp(
 options: DefaultFirebaseOptions.currentPlatform,
 );
 print('Initialized default app $app');

}

